e}th{font-size:12px;color:var(--muted);text-align:left;font-weight:600;background:#fafbfc}th,td{padding:12px 10px;border-bottom:1px solid var(--line);white-space:nowrap}td{font-size:13px}.pill{font-size:12px;border-radius:20px;padding:4px 9px;background:#e8f6ef;color:var(--green)}.pill.gray{background:#eef1f5;color:#687386}.pill.red{background:#fdecec;color:var(--red)}.toolbar{display:flex;gap:10px;margin-bottom:16px}.toolbar input,.toolbar select,.modal input,.modal select{border:1px solid #cfd6e1;border-radius:5px;padding:10px;background:#fff;font:inherit}.toolbar input{width:260px}.table-wrap{overflow:auto}.actions{display:flex;gap:7px}.link{border:0;background:none;color:var(--brand);cursor:pointer;padding:0}.empty{color:var(--muted);padding:24px;text-align:center}.modal-back{display:none;position:fixed;inset:0;background:#0f172a66;align-items:center;justify-content:center}.modal-back.open{display:flex}.modal{background:#fff;border-radius:8px;width:420px;padding:24px;box-shadow:0 20px 50px #0003}.modal h2{margin:0 0 18px}.field{margin:13px 0}.field label{display:block;color:var(--muted);font-size:12px;margin-bottom:6px}.field input,.field select{width:100%}.modal-foot{display:flex;justify-content:flex-end;gap:9px;margin-top:22px}@media(max-width:900px){.side{width:190px}.stats{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}.content{padding:22px}}
