const data=JSON.parse('__PAYLOAD__');let current='overview';const names={overview:'总览',licenses:'卡密管理',devices:'设备管理',audit:'审计日志',settings:'系统设置'};function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function pill(s){let c=s==='revoked'||s==='suspended'?'red':s==='issued'?'gray':'';return `<span class="pill ${c}">${esc(s)}</span>`}function render(){document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{current=b.dataset.view;document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===current));document.querySelector('#crumb').textContent=names[current];if(current==='licenses')renderLicenses()});document.querySelector('#sLic').textContent=data.licenses.length;document.querySelector('#sActive').textContent=data.licenses.filter(x=>x.status==='active').length;document.querySelector('#sDev').textContent=data.devices.length;document.querySelector('#sLog').textContent=data.logs.length;document.querySelector('#recentLic').innerHTML=data.licenses.slice(0,6).map(x=>`<p>${esc(x.key_prefix)}... <span style="float:right">${pill(x.status)}</span></p>`).join('')||'<div class="empty">暂无数据</div>';document.querySelector('#recentLog').innerHTML=data.logs.slice(0,6).map(x=>`<p>${esc(x.action)} <span style="float:right;color:#6d7890">${esc(x.created_at)}</span></p>`).join('')||'<div class="empty">暂无数据</div>';document.querySelector('#devRows').innerHTML=data.devices.map(x=>`<tr><td>${esc(x.key_prefix)}</td><td>${esc(x.device_name)}</td><td>${pill(x.status)}</td><td>${esc(x.last_seen_at)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">暂无设备</td></tr>';document.querySelector('#logRows').innerHTML=data.logs.map(x=>`<tr><td>${esc(x.action)}</td><td>${esc(x.result)}</td><td>${esc(x.reason)}</td><td>${esc(x.created_at)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">暂无日志</td></tr>';renderLicenses()}function renderLicenses(){let q=(document.querySelector('#search')?.value||'').toLowerCase(),f=document.querySelector('#filter')?.value||'';let rows=data.licenses.filter(x=>(!q||x.key_prefix.toLowerCase().includes(q)||x.product_code.toLowerCase().includes(q))&&(!f||x.status===f));document.querySelector('#licRows').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.key_prefix)}</b>...</td><td>${esc(x.product_code)}</td><td>${pill(x.status)}</td><td>${esc(x.max_devices)}</td><td>${esc(x.expires_at||'永久')}</td><td>${esc(x.created_at)}</td><td class="actions"><button class="link" onclick='edit(${JSON.stringify(x)})'>编辑</button><button class="link" style="color:#c23b3b" onclick="removeKey('${x.id}')">删除</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有匹配的卡密</td></tr>'}function openCreate(){document.querySelector('#modal').classList.add('open')}function closeModal(){document.querySelector('#modal').classList.remove('open')}async function createKeys(){let r=await fetch('/admin/licenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({count:+mCount.value,product_code:mProduct.value,max_devices:+mMax.value})});let j=await r.json();closeModal();alert(j.licenses?('生成成功：\n'+j.licenses.join('\n')):JSON.stringify(j));location.reload()}async function removeKey(id){if(confirm('确认删除该卡密？')){await fetch('/admin/licenses/'+id,{method:'DELETE'});location.reload()}}async function edit(x){let status=prompt('状态：issued / active / suspended / revoked',x.status);if(!status)return;await fetch('/admin/licenses/'+x.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});location.reload()}function refresh(){location.reload()}render();
