*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172033;font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif}.top{height:64px;padding:0 32px;display:flex;align-items:center;background:#152238;color:#fff}.top strong{font-size:18px}.top span{margin-left:14px;color:#aebed2}.wrap{max-width:1180px;margin:28px auto;padding:0 20px}.grid{display:grid;grid-template-columns:360px 1fr;gap:20px}.panel{background:#fff;border:1px solid #dce2ea;border-radius:7px;padding:20px;box-shadow:0 1px 2px #0000000a}.panel h2{font-size:16px;margin:0 0 16px}label{display:block;margin:12px 0 5px;color:#58657a}input{width:100%;padding:9px;border:1px solid #bdc7d4;border-radius:4px;font:inherit}button{margin-top:18px;background:#1769aa;border:0;color:#fff;padding:10px 16px;border-radius:4px;font-weight:600;cursor:pointer}.note{margin-top:14px;padding:10px;background:#edf6ff;color:#164d78;border-radius:4px;white-space:pre-wrap}.wide{grid-column:1/-1}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e6eaf0}th{color:#64748b;font-size:12px;text-transform:uppercase}.tag{padding:3px 7px;border-radius:12px;background:#e6f4ea;color:#176b35;font-size:12px}.empty{color:#7a8699;padding:12px 0}</style></head><body>
<div class="top"><strong>卡密验证系统</strong><span>MVP 管理后台</span></div><main class="wrap"><div class="grid"><section class="panel"><h2>生成卡密</h2><form id="create"><label>产品编号</label><input name="product_code" value="debug" required><label>生成数量</label><input name="count" type="number" min="1" max="1000" value="1"><label>最大设备数</label><input name="max_devices" type="number" min="1" value="1"><button>生成并显示一次</button></form><div class="note" id="result">生成的原始卡密仅在这里显示一次。</div></section><section class="panel"><h2>当前概览</h2><p>授权数量：<?=count($licenses)?> &nbsp; 已绑定设备：<?=count($devices)?> &nbsp; 审计事件：<?=count($logs)?></p><p>测试 API：<code>POST /api/v1/licenses/activate</code>、<code>POST /api/v1/licenses/verify</code></p></section><section class="panel wide"><h2>授权列表</h2><?php if(!$licenses):?><div class="empty">尚未生成卡密。</div><?php else:?><table><tr><th>前缀</th><th>产品</th><th>状态</th><th>设备上限</th><th>到期</th><th>创建时间</th></tr><?php foreach($licenses as $x):?><tr><td><?=esc($x['key_prefix'])?>...</td><td><?=esc($x['product_code'])?></td><td><span class="tag"><?=esc($x['status'])?></span></td><td><?=esc($x['max_devices'])?></td><td><?=esc($x['expires_at']?:'永久')?></td><td><?=esc($x['created_at'])?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="panel wide"><h2>已绑定设备</h2><?php if(!$devices):?><div class="empty">暂无设备。</div><?php else:?><table><tr><th>卡密前缀</th><th>设备名称</th><th>状态</th><th>最后验证</th></tr><?php foreach($devices as $x):?><tr><td><?=esc($x['key_prefix'])?></td><td><?=esc($x['device_name'])?></td><td><?=esc($x['status'])?></td><td><?=esc($x['last_seen_at'])?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="panel wide"><h2>最近审计事件</h2><?php if(!$logs):?><div class="empty">暂无事件。</div><?php else:?><table><tr><th>动作</th><th>结果</th><th>原因</th><th>时间</th></tr><?php foreach($logs as $x):?><tr><td><?=esc($x['action'])?></td><td><?=esc($x['result'])?></td><td><?=esc($x['reason'])?></td><td><?=esc($x['created_at'])?></td></tr><?php endforeach;?></table><?php endif;?></section></div></main><script>document.querySelector('#create').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.count=+d.count;d.max_devices=+d.max_devices;let r=await fetch('/admin/licenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});let j=await r.json();document.querySelector('#result').textContent=j.licenses?j.licenses.join('\n'):JSON.stringify(j);setTimeout(()=>location.reload(),1500)};</script></body></html><?php exit;
