if ($method === 'POST' && $path === '/admin/licenses') {
    $count=max(1,min((int)($body['count']??1),1000)); $product=(string)($body['product_code']??'default'); $max=max(1,(int)($body['max_devices']??1)); $expires=$body['expires_at']??null; $durationMap=['forever'=>'永久','hour'=>'1小时','day'=>'1天','week'=>'1周','month'=>'1个月','quarter'=>'一季度','year'=>'1年','custom'=>'自定义']; $durationCode=(string)($body['duration_code']??''); $durationLabel=$durationMap[$durationCode]??trim((string)($body['duration_label']??($expires?'自定义':'永久'))); if(!in_array($durationLabel,$durationMap,true)) $durationLabel=$expires?'自定义':'永久'; $length=max(4,min((int)($body['key_length']??16),128)); $prefix=(string)($body['key_prefix']??''); $suffix=(string)($body['key_suffix']??'');
    if (!preg_match('/^[A-Za-z0-9]*$/',$prefix) || !preg_match('/^[A-Za-z0-9]*$/',$suffix) || strlen($prefix)+strlen($suffix)>$length) json_response(['error'=>'invalid_key_format'],400);
    $out=[]; $chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
    for($i=0;$i<$count;$i++){ $middle=''; for($j=0;$j<$length-strlen($prefix)-strlen($suffix);$j++)$middle.=$chars[random_int(0,strlen($chars)-1)]; $raw=$prefix.$middle.$suffix; $normalized=$raw; $id=bin2hex(random_bytes(16)); $stmt=$db->prepare('INSERT INTO licenses(id,key_prefix,key_hash,key_verify_hash,product_code,status,max_devices,expires_at,created_at,key_cipher,duration_label) VALUES(?,?,?,?,?,?,?,?,?,?,?)'); $stmt->execute([$id,substr($raw,0,12),hash_hmac('sha256',$normalized,$config['pepper']),password_hash($normalized,PASSWORD_ARGON2ID),$product,'issued',$max,$expires,gmdate('c'),key_encrypt($raw,$config['manage_secret']),$durationLabel]); $out[]=$raw; }
