if ($method === 'POST' && $path === '/api/v1/licenses/activate') {
    foreach(['license_key','product_code','device_id'] as $f) if(empty($body[$f])) json_response(['error'=>'invalid_request','field'=>$f],400);
    $key=preg_replace('/[^A-Za-z0-9]/','',(string)$body['license_key']); $hash=hash_hmac('sha256',$key,$config['pepper']); $q=$db->prepare('SELECT * FROM licenses WHERE key_hash=? AND product_code=?'); $q->execute([$hash,$body['product_code']]); $lic=$q->fetch(PDO::FETCH_ASSOC);
    if(!$lic) json_response(['error'=>'invalid_license'],401); if($lic['status']==='suspended'){audit($db,'activate',$lic['id'],null,'fail','license_suspended');json_response(['error'=>'license_suspended'],403);} if($lic['status']==='revoked'){audit($db,'activate',$lic['id'],null,'fail','license_revoked');json_response(['error'=>'license_revoked'],403);} if($lic['status']==='expired'||($lic['expires_at']&&strtotime($lic['expires_at'])<time())){audit($db,'activate',$lic['id'],null,'fail','license_expired');json_response(['error'=>'license_expired'],403);}
    $dh=hash('sha256',(string)$body['device_id']); $q=$db->prepare('SELECT * FROM devices WHERE license_id=? AND device_hash=?'); $q->execute([$lic['id'],$dh]); $dev=$q->fetch(PDO::FETCH_ASSOC); $newDevice=!$dev;
    if($newDevice){ $q=$db->prepare('SELECT COUNT(*) FROM devices WHERE license_id=? AND status="active"'); $q->execute([$lic['id']]); if((int)$q->fetchColumn()>=$lic['max_devices']) { audit($db,'activate',$lic['id'],null,'fail','device_limit_reached'); json_response(['error'=>'device_limit_reached'],409); } $did=bin2hex(random_bytes(16)); $q=$db->prepare('INSERT INTO devices(id,license_id,device_hash,device_name,status,first_seen_at,last_seen_at,online_status) VALUES(?,?,?,?,?,?,?,?)'); $q->execute([$did,$lic['id'],$dh,$body['device_name']??'device','active',gmdate('c'),gmdate('c'),'online']); } else { $did=$dev['id']; $db->prepare('UPDATE devices SET last_seen_at=?,online_status="online" WHERE id=?')->execute([gmdate('c'),$did]); }
    if ($lic['status'] === 'issued') { $db->prepare('UPDATE licenses SET status="active" WHERE id=?')->execute([$lic['id']]); }
    $token=bin2hex(random_bytes(32)); $sid=bin2hex(random_bytes(16)); $exp=time()+$config['session_ttl']; $db->prepare('INSERT INTO sessions VALUES(?,?,?,?,?,NULL)')->execute([$sid,$lic['id'],$did,hash('sha256',$token),gmdate('c',$exp)]); audit($db,$newDevice?'activate':'login',$lic['id'],$did,'ok',$newDevice?'device_bound':'existing_device_login');
    json_response(['request_id'=>$sid,'license'=>['id'=>$lic['id'],'status'=>'active','expires_at'=>$lic['expires_at']],'session_token'=>$token,'session_expires_at'=>gmdate('c',$exp),'server_time'=>gmdate('c')]);
}
if ($method === 'POST' && $path === '/api/v1/licenses/heartbeat') {
    foreach(['license_key','product_code','device_id'] as $f) if(empty($body[$f])) json_response(['error'=>'invalid_request','field'=>$f],400);
    $key=preg_replace('/[^A-Za-z0-9]/','',(string)$body['license_key']); $hash=hash_hmac('sha256',$key,$config['pepper']); $q=$db->prepare('SELECT * FROM licenses WHERE key_hash=? AND product_code=?'); $q->execute([$hash,$body['product_code']]); $lic=$q->fetch(PDO::FETCH_ASSOC);
    if(!$lic){audit($db,'heartbeat',null,null,'fail','invalid_license');json_response(['error'=>'invalid_license'],401);} if($lic['status']==='suspended'){audit($db,'heartbeat',$lic['id'],null,'fail','license_suspended');json_response(['error'=>'license_suspended'],403);} if($lic['status']==='revoked'){audit($db,'heartbeat',$lic['id'],null,'fail','license_revoked');json_response(['error'=>'license_revoked'],403);} if($lic['status']==='expired' || ($lic['expires_at'] && strtotime($lic['expires_at'])<time())){audit($db,'heartbeat',$lic['id'],null,'fail','license_expired');json_response(['error'=>'license_expired'],403);}
    $dh=hash('sha256',(string)$body['device_id']); $q=$db->prepare('SELECT id,status FROM devices WHERE license_id=? AND device_hash=?'); $q->execute([$lic['id'],$dh]); $device=$q->fetch(PDO::FETCH_ASSOC); if(!$device || $device['status']!=='active'){audit($db,'heartbeat',$lic['id'],null,'fail','device_not_bound');json_response(['error'=>'device_not_bound'],403);}
    $db->prepare('UPDATE devices SET last_seen_at=?,online_status="online" WHERE id=?')->execute([gmdate('c'),$device['id']]); audit($db,'heartbeat',$lic['id'],$device['id'],'ok'); json_response(['status'=>'active','expires_at'=>$lic['expires_at'],'server_time'=>gmdate('c')]);
}
if ($method === 'POST' && $path === '/api/v1/licenses/logout') {
    foreach(['license_key','product_code','device_id'] as $f) if(empty($body[$f])) json_response(['error'=>'invalid_request','field'=>$f],400);
    $key=preg_replace('/[^A-Za-z0-9]/','',(string)$body['license_key']); $hash=hash_hmac('sha256',$key,$config['pepper']); $q=$db->prepare('SELECT id FROM licenses WHERE key_hash=? AND product_code=?'); $q->execute([$hash,$body['product_code']]); $lic=$q->fetch(PDO::FETCH_ASSOC); if(!$lic){audit($db,'logout',null,null,'fail','invalid_license');json_response(['error'=>'invalid_license'],401);} $dh=hash('sha256',(string)$body['device_id']); $q=$db->prepare('SELECT id FROM devices WHERE license_id=? AND device_hash=?');$q->execute([$lic['id'],$dh]);$device=$q->fetch(PDO::FETCH_ASSOC); if(!$device){audit($db,'logout',$lic['id'],null,'fail','device_not_bound');json_response(['error'=>'device_not_bound'],403);} $db->prepare('UPDATE devices SET online_status="offline",last_seen_at=? WHERE id=?')->execute([gmdate('c'),$device['id']]); audit($db,'logout',$lic['id'],$device['id'],'ok'); json_response(['status'=>'offline','server_time'=>gmdate('c')]);
}
if ($method === 'POST' && $path === '/api/v1/licenses/verify') {
    verify_request_signature($config,$method,$path,file_get_contents('php://input'));
    $auth=$_SERVER['HTTP_AUTHORIZATION']??''; $token=preg_replace('/^Bearer\s+/i','',$auth); $q=$db->prepare('SELECT s.*,l.status license_status,l.expires_at license_expires_at,d.status device_status FROM sessions s JOIN licenses l ON l.id=s.license_id JOIN devices d ON d.id=s.device_id WHERE s.token_hash=?'); $q->execute([hash('sha256',$token)]); $row=$q->fetch(PDO::FETCH_ASSOC);
    if(!$row || $row['revoked_at'] || strtotime($row['expires_at'])<time()) json_response(['error'=>'session_expired'],401); if($row['license_status']!=='active' || $row['device_status']!=='active' || ($row['license_expires_at'] && strtotime($row['license_expires_at'])<time())) json_response(['error'=>'license_unavailable'],403); audit($db,'verify',$row['license_id'],$row['device_id'],'ok'); json_response(['request_id'=>bin2hex(random_bytes(8)),'status'=>'active','expires_at'=>$row['license_expires_at'],'server_time'=>gmdate('c')]);
}
json_response(['error'=>'not_found'],404);
